cu_num = int(os.getenv("CU_NUM", "0"))
if cu_num == 0 and os.getenv("SMG_SG4_PD_CU_EXISTING_RUNTIME") == "1":
    import torch

    if torch.version.hip is None or not torch.cuda.is_initialized():
        raise RuntimeError("initialized HIP runtime required for current-device CU query")
    visible_count = torch.cuda.device_count()
    logical_device = torch.cuda.current_device()
    if type(visible_count) is not int or visible_count < 1:
        raise RuntimeError("no process-visible HIP devices")
    if type(logical_device) is not int or not 0 <= logical_device < visible_count:
        raise RuntimeError("invalid current logical HIP device")
    current_cu = torch.cuda.get_device_properties(logical_device).multi_processor_count
    if type(current_cu) is not int or current_cu <= 0:
        raise RuntimeError("invalid current HIP compute-unit property")
    return current_cu
